// Une Q1 (epics) con Q2 (hijos, lista plana) y deja un item por Epic.
const test = $('Config').first().json.testEpicKey;
const epics = $('Metabase Q1 Live Epics').all().map(i => i.json).filter(e => e.issue_key);
const kids = $input.all().map(i => i.json).filter(c => c.issue_key && c.parent_link);
const byParent = {};
for (const c of kids) (byParent[c.parent_link] = byParent[c.parent_link] || []).push(c);
const selected = test ? epics.filter(e => e.issue_key === test) : epics;
return selected.map(e => ({ json: { epic: e, children: byParent[e.issue_key] || [] } }));

const hashStr = (s) => { let h1 = 0xdeadbeef, h2 = 0x41c6ce57; for (let i = 0; i < s.length; i++) { const ch = s.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); } h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909); h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909); return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0'); };

const cfg = $('Config').first().json;
const { epic, children } = $('Loop Epics').first().json;
const mapRow = ($('Get Mapping').first() || {}).json || {};
const mapping = mapRow.epic_key ? mapRow : null;
const comments = $input.all().map(i => i.json).filter(c => c && c.id)
  .sort((a, b) => new Date(a.created) - new Date(b.created)).slice(-10).reverse();

const esc = (s) => (s === null || s === undefined) ? '' : String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const val = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.map(val).filter(Boolean).join(', ');
  if (typeof v === 'object') return String(v.value || v.name || v.displayName || v.key || '').trim();
  return String(v).trim();
};
const rawOf = (c) => { let r = c.raw_data; if (typeof r === 'string') { try { r = JSON.parse(r); } catch (e) { r = null; } } return r || {}; };
const cf = (c, id) => { const f = rawOf(c).fields || {}; return val(f['customfield_' + id] !== undefined ? f['customfield_' + id] : c['customfield_' + id]); };
const descOf = (c) => val((rawOf(c).fields || {}).description || c.description);

const etParts = (iso) => {
  if (!iso) return null;
  const d = new Date(iso);
  if (isNaN(d.getTime())) return null;
  const p = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true }).formatToParts(d);
  const g = (t) => (p.find(x => x.type === t) || {}).value || '';
  return { date: `${g('month')}/${g('day')}/${g('year')}`, time: `${g('hour')}:${g('minute')}`, ap: g('dayPeriod').toLowerCase().startsWith('p') ? 'p' : 'a' };
};
// 11/6/2026 - 12:55p ET  (formato del plan)
const fmtET = (iso) => { const p = etParts(iso); return p ? `${p.date} - ${p.time}${p.ap} ET` : (iso ? String(iso) : ''); };

// ---------- Marca -> pagina padre (Wiki Field Mapping) ----------
const BRAND_MAP = [
  { match: ['BVD', 'BOVADA'], name: 'Bovada', parentId: '277422571' },
  { match: ['OZOON'], name: 'Ozoon', parentId: '277422692' },
  { match: ['SLOTS'], name: 'Slots', parentId: '277422699' },
  { match: ['CAFE'], name: 'Cafe Casino', parentId: '277422697' },
  { match: ['JOE FORTUNE', 'JFT'], name: 'Joe Fortune', parentId: '277422702' },
  { match: ['BVX'], name: 'BVX', parentId: '337289266' }
];
const brandList = String(epic.brands_combo || epic.brand || '').toUpperCase().split(/[,;|]/).map(s => s.trim()).filter(Boolean);
const regionStr = String(epic.regions_combo || epic.region || '').toUpperCase();
let brandDisplay = 'All Brands', parentPageId = '277422705';
if (brandList.length === 1) {
  const b = brandList[0];
  if (b.includes('IGN')) {
    if (regionStr.includes('AUS')) { brandDisplay = 'Ignition AUS'; parentPageId = '459091653'; }
    else { brandDisplay = 'Ignition UFM'; parentPageId = '277422694'; }
  } else {
    const hit = BRAND_MAP.find(x => x.match.some(m => b.includes(m)));
    if (hit) { brandDisplay = hit.name; parentPageId = hit.parentId; }
  }
}

// ---------- Datos del Epic ----------
const promoName = (epic.epic_name || '').trim() || (epic.summary || '').replace(/^\[.*?\]\s*/, '').trim();
const startRaw = epic.live_date || epic.ideal_live_date || '';
const bonuses = children.filter(c => (c.issuetype_name || '').toLowerCase() === 'bonus');
const MSG_TYPES = ['edm', 'notification build', 'sms', 'campaign'];
const msgKids = children.filter(c => MSG_TYPES.includes((c.issuetype_name || '').toLowerCase()));
const endRaw = bonuses.map(b => cf(b, '11221')).find(Boolean) || epic.due_date || '';
const audience = [epic.high_level_target_audience, ...bonuses.map(b => cf(b, '26615'))].filter(Boolean).join(' | ');
const eligibility = [epic.high_level_details, epic.high_level_campaign_needs].filter(Boolean).join(' | ');
const bonusIds = bonuses.map(b => cf(b, '11246')).filter(Boolean);

// imagenes de messaging (raw_data.fields.attachment de EDM / Notification / Campaign)
const images = [];
for (const k of msgKids) {
  const atts = (rawOf(k).fields || {}).attachment || [];
  for (const a of atts) if (a && String(a.mimeType || '').startsWith('image/') && a.content) images.push({ key: k.issue_key, type: k.issuetype_name, name: a.filename || 'image', url: a.content });
}
const landing = [];
for (const k of children.filter(c => ['campaign', 'page build'].includes((c.issuetype_name || '').toLowerCase()))) {
  const m = descOf(k).match(/https?:\/\/[^\s)\]|>]+/); if (m) landing.push(m[0]);
}
const tcs = bonuses.map(b => descOf(b)).filter(Boolean).join('\n---\n');

// ---------- Completitud ----------
const missingFields = [];
if (brandList.length === 0) missingFields.push('Brand');
if (!promoName) missingFields.push('Name of Promotion');
if (!startRaw) missingFields.push('Start Date');
if (!audience) missingFields.push('Targeted Audience');
if (!eligibility) missingFields.push('Eligibility');
const flaggedFields = [];
if (bonuses.length > 0 && bonusIds.length === 0) flaggedFields.push('CM Bonus ID');
if (images.length === 0) flaggedFields.push('Player messaging image');
if (bonuses.length > 0 && !tcs) flaggedFields.push('T&Cs');
if (!endRaw) flaggedFields.push('End Date');
const allFlags = [...missingFields, ...flaggedFields];

// ---------- Fingerprint (payload Metabase + hijos + comentarios) ----------
const fingerprint = hashStr(JSON.stringify({
  epic,
  children: children.map(c => ({ k: c.issue_key, t: c.issuetype_name, s: c.status_name, u: c.updated_at, b: cf(c, '11246') })).sort((a, b) => String(a.k).localeCompare(String(b.k))),
  comments: comments.map(c => `${c.id}:${c.updated}`).sort()
}));

let action = 'create';
if (mapping) action = (mapping.status === 'stopped' || mapping.fingerprint !== fingerprint) ? 'update' : 'noop';
const event = action === 'create' ? 'CREATED' : (mapping && mapping.status === 'stopped' ? 'RESUMED' : 'UPDATED');

const startFmt = fmtET(startRaw);
const pageTitle = (mapping && mapping.page_title) ? mapping.page_title : `${brandDisplay} | ${promoName}${startFmt ? ' - ' + startFmt : ''}`;

// ---------- HTML (storage format) ----------
const J = cfg.jiraBaseUrl;
const link = (key) => `<a href="${esc(J + '/browse/' + key)}">${esc(key)}</a>`;
const th = (t) => `<th>${esc(t)}</th>`;
const row = (label, v) => `<tr>${th(label)}<td>${v}</td></tr>`;

const callout = allFlags.length
  ? `<ac:structured-macro ac:name="warning"><ac:rich-text-body><p><strong>Incomplete MAP data:</strong> ${esc(allFlags.join(', '))}</p></ac:rich-text-body></ac:structured-macro>`
  : `<ac:structured-macro ac:name="info"><ac:rich-text-body><p><strong>Status:</strong> all required fields present. Last synced: ${esc(fmtET(new Date().toISOString()))}</p></ac:rich-text-body></ac:structured-macro>`;

const overview = `<h2>Campaign Overview</h2><table><tbody>`
  + row('Brand', esc(brandList.length > 1 ? brandList.join(', ') : brandDisplay))
  + row('Name of Promotion', esc(promoName))
  + row('GMO / MAP Number', link(epic.issue_key))
  + row('Title of Promotion', esc(`${epic.issue_key} - ${epic.summary || ''}`))
  + row('Epic Status', esc(epic.status_name || ''))
  + row('Start Date', esc(fmtET(startRaw)))
  + row('End Date', esc(fmtET(endRaw)))
  + row('Targeted Audience', esc(audience))
  + row('Eligibility / Requirements', esc(eligibility))
  + row('Additional details', esc(epic.high_level_details || ''))
  + `</tbody></table>`;

const bonusHtml = bonuses.length === 0
  ? `<h2>Bonus</h2><p><em>No Bonus child tickets linked yet.</em></p>`
  : `<h2>Bonus</h2>` + bonuses.map(b => {
    const m = cf(b, '26489'), fx = cf(b, '26490'), mx = cf(b, '26491') || cf(b, '25517');
    const amount = [m ? (/%/.test(m) ? m : m + '%') + ' Match' : '', fx ? '$' + fx : '', mx ? 'up to $' + mx : ''].filter(Boolean).join(' ');
    const iss = [cf(b, '18101'), cf(b, '18102')].filter(Boolean).join(' - ') || 'N/A';
    const roll = ['Sports:' + cf(b, '26492'), 'Horses:' + cf(b, '26493'), 'Casino:' + cf(b, '26494'), 'Poker:' + cf(b, '26495')].filter(x => !x.endsWith(':')).join(' | ');
    const bid = cf(b, '11246');
    return `<table><tbody>`
      + row('Ticket', link(b.issue_key) + ' (' + esc(b.status_name || '') + ')')
      + row('Name of Bonus (on site)', esc(cf(b, '26613')))
      + row('Name of Bonus (in CM)', esc(b.summary || ''))
      + row('CM Bonus ID', bid ? `<strong>${esc(bid)}</strong>` : '')
      + row('Bonus Type', esc(cf(b, '11243')))
      + row('Amount $ or %', esc(amount))
      + row('Max Cashout on spins', esc(cf(b, '26606')))
      + row('# of Redemptions', esc(cf(b, '26481')))
      + row('Issuing Timeframe', esc(iss))
      + row('Days after Redemption', esc(cf(b, '11236')))
      + row('Max days bonus is offered', esc(cf(b, '11235')))
      + row('Rollover', esc(roll))
      + row('T&Cs', esc(descOf(b)))
      + `</tbody></table>`;
  }).join('<p></p>');

const msgHtml = `<h2>Player Messaging</h2><table><tbody>`
  + row('Landing page', landing.length ? landing.map(u => `<a href="${esc(u)}">${esc(u)}</a>`).join('<br/>') : '')
  + row('Message to players (images)', images.length ? images.map(i => `<a href="${esc(i.url)}">${esc(i.key + ' - ' + i.name)}</a>`).join('<br/>') : '')
  + `</tbody></table>`;

const kidsHtml = `<h2>All Linked MAP Activities (${children.length})</h2><table><thead><tr>${th('Type')}${th('MAP Key')}${th('Summary')}${th('Status')}</tr></thead><tbody>`
  + (children.length === 0 ? `<tr><td colspan="4"><em>No linked MAP activities found.</em></td></tr>`
    : children.map(c => `<tr><td>${esc(c.issuetype_name || '')}</td><td>${link(c.issue_key)}</td><td>${esc(c.summary || '')}</td><td>${esc(c.status_name || '')}</td></tr>`).join(''))
  + `</tbody></table>`;

const commentsHtml = `<h2>Last 10 Epic Comments</h2><p>Epic: ${link(epic.issue_key)}</p>`
  + (comments.length === 0 ? `<p><em>No comments on Epic.</em></p>`
    : `<ul>${comments.map(c => `<li><strong>${esc((c.author && c.author.displayName) || 'User')}</strong> (${esc(fmtET(c.created))}): ${esc(String(c.body || '').slice(0, 500))}</li>`).join('')}</ul>`);

const storageBody = callout + overview + bonusHtml + msgHtml + kidsHtml + commentsHtml;

return [{
  json: {
    epicKey: epic.issue_key,
    action,
    event,
    pageTitle,
    brandDisplay,
    parentPageId,
    spaceKey: cfg.spaceKey,
    targetPageStatus: cfg.targetPageStatus,
    dbStatus: cfg.targetPageStatus === 'draft' ? 'draft' : 'current',
    existingPageId: mapping ? mapping.confluence_page_id : null,
    fingerprint,
    missingFields,
    flaggedFields,
    allFlags,
    labels: ['map-epic-' + String(epic.issue_key).toLowerCase(), 'map-tracking-active'],
    storageBody
  }
}];

// Seguridad: sin Q1 (vacio/fallo) o en modo prueba, no se detiene nada.
const test = $('Config').first().json.testEpicKey;
const live = new Set($('Metabase Q1 Live Epics').all().map(i => i.json.issue_key).filter(Boolean));
if (test || live.size === 0) return [];
return $input.all().map(i => i.json)
  .filter(r => r.epic_key && !live.has(r.epic_key))
  .map(r => ({ json: { epicKey: r.epic_key, pageId: r.confluence_page_id } }));
